css:
/* LiquidTouch 1.9.0 — original CSS. No remote fonts or scripts. */
:root {
  --lt-bg: #0c101c;
  --lt-ink: #f6f8fc;
  --lt-muted: #d0d9e7;
  --lt-accent: #b4eedc;
  --lt-accent-ink: #0b2822;
  --lt-glass: rgba(28, 39, 58, .76);
  --lt-border: rgba(228, 242, 255, .19);
  --lt-shadow: 0 12px 38px #03071355, inset 0 1px 0 #ffffff1f;
  --lt-touch: 48px;
  --lt-row: 64px;
  --lt-header: 64px;
  --lt-mini: 72px;
  --lt-nav: 64px;
  --lt-footer: calc(var(--lt-mini) + var(--lt-nav) + 28px + env(safe-area-inset-bottom, 0px));
  --lt-keyboard-height: 260px;
  --lt-art-color: #354464;
  --lt-art-rgb: 53, 68, 100;
  --lt-glass-rgb: 25, 34, 49;
  --lt-glass-opacity: .35;
  --lt-text-scale: 1.2;
  --lt-ui-scale: 1;
  --lt-keyboard-scale: 1.45;
  --lt-artwork-scale: 1.35;
  --lt-chrome-height: 0px;
}

/* Theme alone is deliberately usable; desktop chrome is hidden ONLY when
   the extension has mounted and found Spotify's main view. */
body {
  background: var(--spice-main, var(--lt-bg));
}
.Root__main-view, .Root__nav-bar {
  border-radius: 20px;
}

body.lt-active {
  --background-base: var(--lt-bg);
  --background-highlight: #222c3e;
  --background-elevated-base: #202b40;
  --text-base: var(--lt-ink);
  --text-subdued: var(--lt-muted);
  min-width: 0 !important;
  overflow: hidden;
  color: var(--lt-ink);
  background: var(--lt-bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  -webkit-tap-highlight-color: transparent;
}
body[data-lt-size="large"] {
  --lt-touch: 56px;
  --lt-row: 72px;
  --lt-header: 72px;
  --lt-mini: 80px;
  --lt-nav: 72px;
}
body[data-lt-palette="ocean"] {
  --lt-bg: #091520;
  --lt-accent: #a8dfff;
  --lt-accent-ink: #102536;
  --lt-glass: rgba(22, 47, 65, .82);
}
body[data-lt-palette="graphite"] {
  --lt-bg: #101114;
  --lt-accent: #e4e7ef;
  --lt-accent-ink: #1a1e25;
  --lt-glass: rgba(39, 42, 49, .86);
}

/* Native Spotify browsing area. Nodes stay in Spotify's React tree. */
body.lt-active .Root {
  position: fixed !important;
  inset: 0 !important;
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  overflow: hidden;
  isolation: isolate;
  background: radial-gradient(ellipse at 10% -15%, rgba(var(--lt-art-rgb), .24), transparent 65%),
    radial-gradient(ellipse at 95% 90%, rgba(var(--lt-art-rgb), .13), transparent 65%), var(--lt-bg) !important;
}
body.lt-active :is(.Root__globalNav, .Root__top-bar, .Root__right-sidebar,
  .Root__now-playing-bar, .main-topBar-container, .main-buddyFeed-buddyFeedRoot,
  .main-resizeBar-resizeBar, .main-yourLibraryX-resizeBar) {
  display: none !important;
}
body.lt-active :is(.Root__main-view, [data-lt-native="main"]) {
  position: fixed !important;
  inset: calc(var(--lt-chrome-height) + var(--lt-header) + 6px) 12px var(--lt-footer-measured, calc(var(--lt-footer) + 4px)) !important;
  display: flex !important;
  flex-direction: column;
  width: auto !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: none !important;
  margin: 0 !important;
  border: 1px solid #ffffff09;
  border-radius: 24px;
  background: #ffffff03 !important;
  overflow: hidden;
  z-index: 1;
}
body.lt-active :is(.main-view-container, .main-view-container__scroll-node,
  .main-view-container__scroll-node-child) {
  width: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
}
body.lt-active :is(.main-view-container, .main-view-container__scroll-node) {
  height: 100% !important;
}
body.lt-active .main-view-container__scroll-node {
  overflow-y: auto !important;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
}
body.lt-active .Root__nav-bar { display: none !important; }
body.lt-active[data-lt-page="library"] :is(.Root__main-view, [data-lt-native="main"]) {
