@media(max-width:620px){#lt-settings .lt-settings-home { grid-template-columns:minmax(0,1fr); }}
#lt-settings .lt-settings-content { position:relative;z-index:2; }
#lt-settings .lt-settings-back-preview { position:absolute;z-index:1;overflow:hidden;pointer-events:none;padding:8px 20px 20px; }
#lt-settings { width:min(900px,calc(100vw - 24px));max-width:calc(100vw - 24px); }
@media(max-height:540px) and (min-width:621px){
  #lt-settings .lt-settings-home { gap:8px; }
  #lt-settings .lt-settings-category { min-height:64px;padding:10px 12px; }
  #lt-settings .lt-settings-category-copy > span { display:none; }
}

/* 1.9.3: lyric space is reclaimed when there is no loading/error status. */
#lt-lyrics-status:empty { display:none; }
#lt-now-playing .lt-lyrics-heading { margin-bottom:0; }
:where(#lt-shell,.lt-dialog) button,#lt-rescue { transition-duration:var(--lt-button-time,80ms); }
#lt-now-playing .lt-lyric-line { transition-duration:var(--lt-lyric-time,100ms); }
.lt-setting .lt-toggle::before,.lt-opacity-mode .lt-toggle::before { transition-duration:var(--lt-toggle-time,160ms); }
.lt-search-preview[aria-busy="true"] .lt-preview-status::before { animation-duration:var(--lt-spinner-time,800ms); }
#lt-settings .lt-motion-options { border:1px solid #ffffff30;border-radius:calc(var(--lt-radius)*.65);padding:10px 12px;margin:12px 0; }
#lt-settings .lt-motion-options summary { min-height:44px;align-content:center;font-size:calc(16px * var(--lt-text-scale));font-weight:650;cursor:pointer;touch-action:manipulation; }

/* 1.9.4: one player canvas, bounded artwork flow and owned action sheets. */
#lt-now-playing .lt-np-header {
  position:relative;top:auto;z-index:3;background:none !important;
  backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:none;
}
#lt-now-playing .lt-np-layout { overflow:hidden; }
#lt-now-playing .lt-np-record { justify-content:safe center;align-content:safe center; }
#lt-now-playing .lt-art-area { min-height:min-content; }
#lt-now-playing[data-lyrics="false"] .lt-np-record { align-items:start;grid-auto-rows:max-content; }
#lt-now-playing .lt-art-frame:focus-visible { outline:3px solid var(--lt-accent);outline-offset:3px; }
.lt-history-actions { display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:10px; }
.lt-history-limit { display:flex;align-items:center;gap:16px;flex-wrap:wrap;font-size:calc(15px * var(--lt-text-scale)); }
.lt-history-limit select { min-height:48px;padding:8px 16px;font:inherit;color:var(--lt-ink);background:rgba(var(--lt-glass-rgb),.8);border:1px solid #ffffff40;border-radius:var(--lt-radius); }
.lt-history-limit option { background:var(--lt-bg);color:var(--lt-ink); }
.lt-danger { color:#ffb8c4 !important; }
#lt-utility {
  width:min(720px,calc(100vw - 24px));max-width:calc(100vw - 24px);max-height:calc(100dvh - 24px);
  border-radius:var(--lt-radius);padding:0;overflow:hidden;isolation:isolate;
  background:rgba(var(--lt-glass-rgb),var(--lt-surface-opacity));
  backdrop-filter:blur(calc(18px * var(--lt-surface-opacity)));-webkit-backdrop-filter:blur(calc(18px * var(--lt-surface-opacity)));
}
#lt-utility[open] { display:flex;flex-direction:column; }
#lt-utility::backdrop { background:#03071155;backdrop-filter:none; }
body.lt-active[data-lt-window="custom"] #lt-utility .lt-windowbar {
  position:relative;inset:auto;width:var(--lt-caption-width,146px);height:auto;
  flex:0 0 auto;margin:6px 10px 0 auto;
}
#lt-utility .lt-sheet-header { position:relative;flex:0 0 auto;background:none;box-shadow:none;border:0; }
.lt-utility-content { flex:1 1 auto;min-height:0;overflow:auto;overscroll-behavior:contain;touch-action:pan-y;padding:0 20px 20px; }
#lt-utility-status { color:var(--lt-muted);font-size:calc(14px * var(--lt-text-scale)); }
#lt-utility-status:empty { display:none; }
#lt-utility-subtitle { overflow-wrap:anywhere; }
#lt-utility-body { display:flex;flex-direction:column;gap:8px; }
#lt-utility-body h3 { font-size:calc(17px * var(--lt-text-scale));margin:12px 0 4px; }
.lt-utility-cover { width:100px;height:100px;object-fit:cover;border-radius:calc(var(--lt-radius)*.7);align-self:center;margin:0 0 10px; }
#lt-utility .lt-utility-option,#lt-utility .lt-utility-entity {
  display:flex;align-items:center;justify-content:flex-start;gap:14px;text-align:left;white-space:normal;
  min-height:max(48px,var(--lt-touch));width:100%;border-radius:calc(var(--lt-radius)*.65);
  padding:12px 16px;background:#ffffff0c;font-size:calc(16px * var(--lt-text-scale));
}
#lt-utility .lt-utility-option small { margin-left:auto;font-size:calc(12px * var(--lt-text-scale));color:var(--lt-muted); }
.lt-utility-entity img { width:56px;height:56px;flex:none;object-fit:cover;border-radius:calc(var(--lt-radius)*.45); }
.lt-utility-copy { display:flex;flex-direction:column;gap:4px;min-width:0;overflow-wrap:anywhere; }
.lt-utility-copy small { color:var(--lt-muted);font-size:calc(13px * var(--lt-text-scale)); }
.lt-utility-row { display:flex;align-items:center;gap:6px; }
#lt-utility .lt-utility-row .lt-utility-entity { flex:1;min-width:0; }
#lt-utility .lt-utility-row .lt-utility-option { width:auto;font-size:calc(13px * var(--lt-text-scale)); }
#lt-utility:is([data-lt-clear="true"],[data-lt-solid="true"]),body[data-lt-lite="true"] #lt-utility { backdrop-filter:none;-webkit-backdrop-filter:none; }
@media(max-width:700px) {
  #lt-now-playing[open] { overflow:hidden; }
  #lt-now-playing .lt-np-layout { flex:1 1 0;min-height:0;overflow-y:auto;align-content:start; }
  #lt-now-playing .lt-np-record { overflow:visible;justify-content:flex-start; }
  #lt-now-playing[data-lyrics="false"] .lt-np-record { align-items:center; }
}

/* Revised 1.9.4: a balanced journal with one compact header and readable rows. */
#lt-history {
  inset:12px;margin:0 auto;width:min(1120px,calc(100vw - 24px));max-width:calc(100vw - 24px);
  height:calc(100dvh - 24px);max-height:calc(100dvh - 24px);
}
body.lt-active #lt-history .lt-np-header,
body.lt-active[data-lt-window="custom"] #lt-history .lt-np-header {
  padding:18px 24px 12px;margin:0;flex:0 0 auto;gap:16px;align-items:center;
}
#lt-history .lt-context { text-align:left; }
#lt-history [data-action="closeHistory"] {
  margin:0;flex:none;align-self:flex-start;border-radius:50%;background:#ffffff0c;
}
#lt-history-title { margin:0;font-size:calc(23px * var(--lt-text-scale));line-height:1.2; }
.lt-history-caption { margin:5px 0 0;color:var(--lt-muted);font-size:calc(13px * var(--lt-text-scale)); }
#lt-history .lt-history-tools {
  display:grid;grid-template-columns:minmax(240px,1fr) auto;gap:12px 20px;
  padding:12px 24px 18px;flex:none;
}
#lt-history .lt-field { min-width:0;width:100%;align-self:end; }
#lt-history .lt-history-actions { margin:0;gap:12px;align-items:end;flex-wrap:nowrap; }
#lt-history .lt-history-limit { flex-direction:column;align-items:start;gap:5px;font-size:calc(12px * var(--lt-text-scale)); }
#lt-history .lt-history-limit select { min-height:44px;max-width:170px;padding:7px 12px;font-size:calc(13px * var(--lt-text-scale)); }
#lt-history .lt-history-actions > button { min-height:44px;padding:9px 14px;background:#ffffff09;white-space:nowrap;font-size:calc(13px * var(--lt-text-scale)); }
#lt-history-count { margin:0;font-size:calc(13px * var(--lt-text-scale));color:var(--lt-muted); }
.lt-history-note { margin:0;text-align:right;color:var(--lt-muted);font-size:calc(12px * var(--lt-text-scale)); }
#lt-history-status { grid-column:1 / -1;margin:0; }
#lt-history-status:empty { display:none; }
#lt-history .lt-history-list { padding:0 24px 24px;scroll-padding:12px; }
#lt-history .lt-history-day { margin:8px 0 12px;padding-top:12px;border-top:1px solid #ffffff1c;font-size:calc(15px * var(--lt-text-scale)); }
#lt-history .lt-history-row { padding:14px 16px;margin-bottom:8px;gap:16px; }
#lt-history .lt-history-row time { font-size:calc(12px * var(--lt-text-scale));font-variant-numeric:tabular-nums; }
@media(max-width:1000px) {
  #lt-history .lt-history-tools { grid-template-columns:minmax(0,1fr);gap:12px; }
  #lt-history .lt-history-actions { justify-content:space-between;align-items:center; }
  #lt-history .lt-history-limit { flex-direction:row;align-items:center;gap:12px; }
  #lt-history .lt-history-note { display:none; }
}
@media(max-height:620px) {
  body.lt-active #lt-history .lt-np-header,
  body.lt-active[data-lt-window="custom"] #lt-history .lt-np-header { padding:12px 20px 8px; }
  #lt-history .lt-history-caption { display:none; }
  #lt-history .lt-history-tools { padding:8px 20px 12px;gap:8px 16px; }
  #lt-history .lt-history-list { padding:0 20px 20px; }
}
@media(max-width:500px) {
  body.lt-active #lt-history .lt-np-header,
  body.lt-active[data-lt-window="custom"] #lt-history .lt-np-header { padding:16px;gap:12px; }
  #lt-history .lt-history-tools { padding:8px 16px 12px; }
  #lt-history .lt-history-limit { flex-direction:column;align-items:start;gap:4px; }
  #lt-history .lt-history-list { padding:0 16px 16px; }
  #lt-history .lt-history-row { gap:10px;padding:12px; }
}
/* The search surface and keyboard stay sharp above a single blurred backdrop. */
#lt-shell .lt-quick-backdrop {
  display:none;position:fixed;inset:0;z-index:10;pointer-events:auto;
  width:100%;height:100%;margin:0;padding:0;border:0;border-radius:0;
  background:rgba(3,7,15,.24) !important;box-shadow:none;
  backdrop-filter:blur(var(--lt-quick-search-blur,14px));-webkit-backdrop-filter:blur(var(--lt-quick-search-blur,14px));
}
body[data-lt-quick="true"] #lt-shell .lt-quick-backdrop { display:block; }
body[data-lt-quick="true"] #lt-shell > :is(.lt-header,.lt-windowbar) { visibility:hidden !important;pointer-events:none; }
body[data-lt-quick="true"] #lt-quick-search { top:calc(var(--lt-chrome-height) + 12px); }
body[data-lt-quick="true"] #lt-search-preview { top:calc(var(--lt-chrome-height) + var(--lt-touch) + 42px); }
.lt-history-art { width:calc(54px * var(--lt-ui-scale));height:calc(54px * var(--lt-ui-scale));flex:none;border-radius:calc(var(--lt-radius)*.4); }
.lt-history-placeholder { display:flex;align-items:center;justify-content:center;background:#ffffff0d;color:var(--lt-muted); }
.lt-history-placeholder svg { width:26px;height:26px; }
.lt-history-text small:empty { display:none; }

/* 1.9.5: center a lyrics-off deck while keeping oversized art safely scrollable. */
#lt-now-playing[data-lyrics="false"] .lt-np-record { align-items:safe center; }
#lt-now-playing[data-lyrics="false"] .lt-np-controls { align-self:safe center;text-align:center; }
#lt-now-playing[data-lyrics="false"] .lt-np-track { position:relative;padding:0 44px; }
#lt-now-playing[data-lyrics="false"] .lt-np-track > div { width:100%; }
#lt-now-playing[data-lyrics="false"] .lt-np-track > button { position:absolute;right:0;top:50%;transform:translateY(-50%); }
#lt-history .lt-keyboard { position:absolute;inset:auto 0 0;z-index:10; }
body[data-lt-history-keyboard="true"] #lt-history .lt-history-list { margin-bottom:var(--lt-history-keyboard-height,0px); }
body[data-lt-history-keyboard="true"] #lt-history :is(.lt-history-actions,.lt-history-caption,.lt-history-note,#lt-history-count) { display:none; }
body[data-lt-low-memory="true"] :is(.lt-atmosphere img,.lt-player-wallpaper img) { display:none; }
body[data-lt-low-memory="true"] :is(.lt-glass,#lt-settings::before,#lt-history::before,#lt-utility,.lt-quick-backdrop) { backdrop-filter:none !important;-webkit-backdrop-filter:none !important; }
.lt-utility-stage { display:flex;flex-direction:column;flex:1 1 auto;min-height:0;max-height:calc(100dvh - 24px);width:100%;border-radius:inherit;overflow:hidden; }
#lt-utility[data-kind="context"] { width:min(420px,calc(100vw - 24px));background:none !important;border:0;box-shadow:none;backdrop-filter:none;-webkit-backdrop-filter:none; }
#lt-utility[data-kind="context"] .lt-utility-stage { background:rgba(var(--lt-glass-rgb),var(--lt-surface-opacity));border:1px solid #ffffff45;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);box-shadow:0 16px 40px #0005; }
#lt-utility[data-kind="context"] .lt-utility-cover { width:56px;height:56px;margin-bottom:2px; }
body[data-lt-low-memory="true"] #lt-utility .lt-utility-stage { backdrop-filter:none;-webkit-backdrop-filter:none; }
@media(max-width:620px) { #lt-utility[data-kind="context"] { width:calc(100vw - 24px); } }
.lt-page-preview { z-index:4;pointer-events:none !important;will-change:transform;contain:layout paint style; }
.lt-utility-back-preview { position:absolute;inset:0;pointer-events:none;z-index:0;overflow:hidden; }
#lt-utility .lt-utility-stage:not(.lt-utility-back-preview) { position:relative;z-index:1; }
.lt-quick-gesture-preview { top:calc(var(--lt-chrome-height) + 12px);pointer-events:none; }
.lt-dialog[data-lt-sheet-drag="true"]::backdrop { background:rgba(3,7,17,calc(.4 * var(--lt-backdrop-fade,1))); }

/* 1.9.6: low-memory mode avoids GPU-heavy filters, shadows and animation layers. */
body[data-lt-low-memory="true"] :is(#lt-shell,.lt-dialog,.lt-atmosphere),
body[data-lt-low-memory="true"] :is(#lt-shell,.lt-dialog,.lt-atmosphere) *,
body[data-lt-low-memory="true"] :is(#lt-shell,.lt-dialog) *::before,
body[data-lt-low-memory="true"] :is(#lt-shell,.lt-dialog) *::after,
body[data-lt-low-memory="true"] .lt-dialog::before,
body[data-lt-low-memory="true"] .lt-dialog::after,
body[data-lt-low-memory="true"] .lt-dialog::backdrop {
  backdrop-filter:none !important;-webkit-backdrop-filter:none !important;
  filter:none !important;box-shadow:none !important;text-shadow:none !important;
  animation:none !important;transition:none !important;scroll-behavior:auto !important;
}
body[data-lt-low-memory="true"] :is(.lt-detail-track,.lt-history-row) {
  content-visibility:auto;contain-intrinsic-size:auto 90px;
}
body.lt-active :is(.lt-utility-content,.lt-release-content,.lt-history-list,.lt-settings-content,#lt-lyrics-lines) {
  overscroll-behavior:contain;touch-action:pan-y;
}

body[data-lt-low-memory="true"] .lt-card { content-visibility:auto;contain-intrinsic-size:auto 280px; }
